llm.raw_content:
{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Hydroxysafflor yellow A, a highly polar glycoside with molecular weight >600, reached 1026 ng/g in rat brain, demonstrating that large polar carbohydrate-containing molecules can achieve meaningful CNS exposure despite unfavorable passive permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Fludarabine, a polar nucleoside, shows transporter-mediated brain uptake in mice, indicating that active uptake at the BBB can overcome physicochemical polarity for nucleoside-like scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Nelarabine exhibited excellent CSF penetration in non-human primates, providing direct evidence that polar glycosylated nucleosides can achieve adequate CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Guanosine enters the CNS within minutes and increases CSF concentrations after systemic administration via nucleoside transporters, supporting transporter-mediated CNS access for polar guanine-related molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Vidarabine achieved CSF-to-plasma ratios of 35-66% in humans, demonstrating meaningful CNS access for a polar nucleoside after systemic dosing.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the query is physicochemically predicted to have low passive BBB permeability, multiple transferable experimental records show that polar, high-MW glycosides and nucleosides can achieve meaningful brain/CSF exposure via active or transporter-mediated routes; therefore predict pass.",
  "evidence_gaps": [
    "No direct experimental CNS exposure data for streptomycin itself; all evidence comes from glycoside/nucleoside analogues.",
    "The query's polycationic guanidine groups may engage different transporters or efflux mechanisms not captured by the analogue set.",
    "Brain/CSF detection in analogues does not always establish therapeutically adequate concentrations for the query's intended use.",
    "Some records involve BBB disruption (e.g., TBI), which may overestimate normal BBB penetration."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

